<template><section><div class="page-heading"><div><h1>{{ canEdit ? '商品工作台' : '商品事实查询' }}</h1><p>{{ canEdit ? '维护商品、SKU、成本与预估毛利事实；不提供自动调价或平台同步。' : '客服仅可查看已授权的商品、SKU、成本和预估毛利事实，不能修改。' }}</p></div><el-button v-if="canEdit" type="primary" @click="router.push('/products/new')">新增商品</el-button></div>
  <el-alert v-if="error" type="error" :title="error" show-icon :closable="false" class="notice" /><div class="panel">
  <el-table v-loading="store.loading" :data="store.products" empty-text="暂无商品数据"><el-table-column prop="name" label="商品" min-width="220"/><el-table-column prop="category" label="类目" width="150"/><el-table-column label="SKU" width="90"><template #default="{row}">{{ row.skus?.length || 0 }}</template></el-table-column><el-table-column prop="status" label="状态" width="120"><template #default="{row}"><el-tag type="success" effect="plain">{{ row.status === 'active' ? '可维护' : row.status }}</el-tag></template></el-table-column><el-table-column label="操作" width="110"><template #default="{row}"><el-button link type="primary" @click="router.push(`/products/${row.id}`)">查看与编辑</el-button></template></el-table-column></el-table>
  </div></section></template>
<script setup lang="ts">import { computed, onMounted, ref } from "vue"; import { useRouter } from "vue-router"; import { useProductStore } from "../stores/product"; import { useAuthStore } from "../stores/auth"; import { errorMessage } from "../api/client"; const store=useProductStore(),auth=useAuthStore(),router=useRouter(),error=ref(""); const canEdit=computed(()=>auth.user?.role==="admin"||auth.user?.role==="operator_content"); onMounted(async()=>{try{await store.fetchProducts()}catch(e){error.value=errorMessage(e)}});</script><style scoped>.notice{margin-bottom:14px}</style>
